mapper.select:
SELECT id,card_id,account_id,payment_date,amount,occurrence_id,false AS grouped FROM card_payment WHERE card_id=#{id}
UNION ALL
SELECT g.id,o.card_id,g.account_id,g.actual_date AS payment_date,g.actual_amount AS amount,g.id AS occurrence_id,true AS grouped
FROM planned_occurrence o JOIN planned_occurrence g ON g.id=o.payment_group_id WHERE o.card_id=#{id}
ORDER BY payment_date DESC,id DESC

SELECT * FROM (
  SELECT DISTINCT ON (i.owner_code, i.details->>'accountId', i.details->>'symbol', i.details->>'currencyCode', i.details->>'priceDate')
    i.owner_code, i.details::text AS details, s.captured_at, s.id AS snapshot_id
  FROM snapshot_item i JOIN asset_snapshot s ON s.id=i.snapshot_id
  WHERE i.item_type='POSITION' AND i.details->>'dailyReturn' IS NOT NULL
    AND i.details->>'priceDate' BETWEEN #{from} AND #{to}
  AND i.owner_code=#{owner}
  AND i.details->>'accountId'=#{account}
  ORDER BY i.owner_code, i.details->>'accountId', i.details->>'symbol', i.details->>'currencyCode', i.details->>'priceDate',
    i.details->>'priceFetchedAt' DESC, s.captured_at DESC, s.id DESC, i.id DESC
) history ORDER BY details::jsonb->>'priceDate' DESC, details::jsonb->>'symbol', details::jsonb->>'accountId'
